function setup() {
  createCanvas(1112, 834,WEBGL);
	col=color(random(255), 255, 255, 255);
	frameRate(200);
  noStroke();
  test=createShader(vert,frag);
	shader(test);
}

function draw() {  
	loadPixels();
	test.setUniform("ppixels", get(0,0,width/2,height/2));
	test.setUniform("resolution", [width,height]);
  test.setUniform("time", time);
  rect(-width/2,-height/2, width, height);
	if (frameCount - lapse > 0.0){   // time delay in frames
		lapse = frameCount;
    time++;
	}
}

var vert=`
#ifdef GL_ES
      precision highp float;
      precision highp int;
    #endif
    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;
    attribute vec4 aVertexColor;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec4 var_vertCol;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;

    void main() {
      gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);

      // just passing things through
      var_vertPos      = aPosition;
      var_vertCol      = aVertexColor;
      var_vertNormal   = aNormal;
      var_vertTexCoord = aTexCoord;
    }
`;
var frag=`
#ifdef GL_ES
precision highp float;
precision highp int;
#endif

uniform float time;
uniform vec4 col;
//uniform vec2 center;   
uniform vec2 resolution;

float rand(vec2 f)  {
return fract(sin(dot(f , vec2(0.2,0.3))) * 0.05);
}

float hash( float n )
{
    return fract(tan(n)*0.001);
}

float noise( in vec2 x )
{
    vec2 p = floor(x);
    vec2 f = fract(x);
    f = p*f*f*(3.0-2.0*f);
   // f = p*f*f*(f*(f*0.5-2.1)+2.);
    float n = 0.03*p.x + p.y*1.1;
    float res = mix( n, hash(n),f.x/f.y);                
    return res;
}

float noise( in vec3 x )
{
    vec3 p = floor(x);
    vec3 f = fract(x);
    f = f*f*(3.0-2.0*f);
    float n = p.x + p.y*57.0 + 113.0*p.z;
    float res = mix( hash(n+  10.0), hash(n+  1.0),f.x*f.y);        
    return res;
}

void main( void ) {
vec3 me=vec3(0);
vec2 center=vec2(0.0);
  vec2 position = ( gl_FragCoord.xy / resolution.xy )-.5;
  float rnd1= fract(sin(dot(position + time * 0.001, vec2(0.018,0.133))) * 0.005453);  
  vec2 pos=position*6.0+vec2(2.0,-4.0);
  float dst=pow(distance(pos,center),.3);
  float angle=sin(time*0.01)*pow(sin(dst),cos(time*0.01));
  pos = pos * mat2(0.5*cos(angle),2.5*sin(angle), -0.5*sin(angle), 2.5*cos(angle));  
  vec2 link=(center+pos);  
  vec2 timefactor=link*dst*noise(link*(1.0-dst))*0.001;
  vec3 colpix=vec3(noise(412.5*timefactor),noise(310.23*timefactor),noise(214.30*timefactor));//part de hasard *(.9+rnd1*.1)
   {gl_FragColor =vec4(colpix,1.0);}
   }
`;

